\label{thm-chi}
 Let $\mathfrak{M}_{{\mathcal P}}$ be a solenoidal manifold with base $M_0$ defined by a group chain ${\mathcal G}$ in $\Gamma = \pi_1(M_0, x_0)$. Then there is a well-defined characteristic map
\begin{equation}\label{eq-chi}
\chi \colon {\rm Mod}(\mathfrak{M}_{{\mathcal P}} ; \widehat{x})  \to {\rm Comm}(\Gamma) \ .
\end{equation}

\label{def-dyncomm}
Let $({\mathfrak{X}}, \Gamma, \Phi)$ be an odometer. For  $x \in {\mathfrak{X}}$, the \emph{dynamical commensurator group} of $({\mathfrak{X}}, \Gamma, \Phi)$ at $x$ is the set of germs of dynamical commensurators,
\begin{equation}\label{eq-dyncomm}
{\rm Comm}({\mathfrak{X}}, \Gamma, \Phi, x) = \{ h \colon U \to V \mid x \in U \cap V\} \slash  \mathrel{\stackrel{\makebox[0pt]{\mbox{\normalfont\tiny c}}}{\sim}}  \  .
\end{equation}

\label{thm-charmap}
Suppose that $\mathfrak{M}_{{\mathcal P}}$ and $\mathfrak{M}'_{{\mathcal P}'}$ are   solenoidal manifolds.
  If $\mathfrak{M}_{{\mathcal P}}$ and $\mathfrak{M}'_{{\mathcal P}'}$ are homeomorphic,  then their monodromy odometers  $({\mathfrak{X}}_0, \Gamma, \Phi)$ and  $({\mathfrak{X}}_0', \Gamma', \Phi')$ are  return equivalent. Moreover, for $x \in {\mathfrak{X}}_0$  corresponding to $\widehat{x} \in \mathfrak{M}_{{\mathcal P}}$, there is a well-defined characteristic map
  \begin{equation}
\sigma_{{\mathcal P},  \widehat{x}} \colon {\rm Mod}(\mathfrak{M}_{{\mathcal P}} ; \widehat{x}) \to {\rm Comm}({\mathfrak{X}}_0, \Gamma, \Phi, x) \ .
\end{equation}

\label{def-regular}
An odometer action $({\mathfrak{X}}_0, \Gamma, \Phi)$ is \emph{regular} if there exists  
\begin{equation}\label{eq-regular}
\Theta_{{\mathcal P}} \colon {\rm Comm}({\mathfrak{X}}_0, \Gamma, \Phi, x) \to {\rm Comm}(\Gamma)
\end{equation}
 such that the diagram \eqref{eq-diagram} commutes, and $\Theta_{{\mathcal P}}$ is an injection.

\label{thm-homogeneous}
Let $\mathfrak{M}_{{\mathcal P}}$ be a homogeneous solenoidal manifold. 
Assume the baseleaf $L_{\widehat{x}} \subset \mathfrak{M}_{{\mathcal P}}$ is simply connected. Then we have a topological isomorphism
\begin{equation}\label{eq-fullprod}
{\rm Mod}(\mathfrak{M}_{{\mathcal P}}) \cong  {\mathfrak{G}}_{{\mathcal G}}   \times_{\zeta} {\rm Mod}(\mathfrak{M}_{{\mathcal P}} ; \widehat{x})   \ .
\end{equation}

\label{cor-homogeneous}
  Let $M_0$ be an ultra Borel   manifold, and assume that  $\mathfrak{M}_{{\mathcal P}}$ is a homogeneous   solenoid over $M_0$ with a simply connected baseleaf $L_{\widehat{x}} \subset \mathfrak{M}_{{\mathcal P}}$. Then 
  \begin{equation}\label{eq-fullproddyn}
{\rm Mod}(\mathfrak{M}_{{\mathcal P}}) \cong    {\mathfrak{G}}_{{\mathcal G}}   \times_{\zeta} {\rm Comm}({\mathfrak{X}}_0, \Gamma, \Phi, x)  \ .
\end{equation}

\label{thm-nonhomogeneous}
Let $\mathfrak{M}_{{\mathcal P}}$ be a solenoidal manifold. 
Assume the baseleaf $L_{\widehat{x}} \subset \mathfrak{M}_{{\mathcal P}}$ is simply connected. Then there is an injection of topological spaces
\begin{equation}\label{eq-tau}
  \overline{\mu}_{{\mathcal G}} \colon  {\mathfrak{A}}_{{\mathcal G}}  \times_{\zeta} {\rm Mod}(\mathfrak{M}_{{\mathcal P}} ; \widehat{x})    \to {\rm Mod}(\mathfrak{M}_{{\mathcal P}})  \ .
\end{equation}

\label{cor-nonhomogeneous}
       Let $M_0$ be an ultra Borel   manifold with a simply connected baseleaf $L_{\widehat{x}} \subset \mathfrak{M}_{{\mathcal P}}$. Then there is an injection of topological spaces 
  \begin{equation}\label{eq-partialproddyn}
 \overline{\mu}_{{\mathcal G}} \colon {\mathfrak{A}}_{{\mathcal G}} \times_{\zeta} {\rm Comm}({\mathfrak{X}}_0, \Gamma, \Phi, x)   \to  {\rm Mod}(\mathfrak{M}_{{\mathcal P}}) \ .
\end{equation}

\cite[Corollary~5.2]{RT1972b}\label{thm-RT}
     Let $M_0$ be a closed connected manifold, and  $\mathfrak{M}_{{\mathcal P}}$ be a solenoidal manifold over $M_0$ defined by a presentation ${\mathcal P}$.  Given a self-homeomorphism  $h \colon \mathfrak{M}_{{\mathcal P}} \to \mathfrak{M}_{{\mathcal P}}$ and ${\varepsilon} > 0$,  then  $h$ is ${\varepsilon}$-homotopic to a continuous map   induced by a \emph{shuffle map} of ${\mathcal P}$. That is, there exists    an increasing sequence   $i_{\ell} \geq \ell$, and continuous maps $\varphi_{i_\ell} \colon M_{i_{\ell}} \to M_{\ell}$  so that the ``zig-zag'' diagram \eqref{eq-shuffle} commutes
 \begin{align} \label{eq-shuffle}
 \xymatrix{ M_{0}   & \ar[l] M_{i_0} \ar[ld]^{\varphi_{i_0}}& \ar[l] M_{i_1} \ar[ld]^{\varphi_{i_1}} & \ar[l] M_{i_2} \ar[ld]^{\varphi_{i_2}}  & \ar[l] \cdots \\
M_0 & \ar[l] M_1  & \ar[l] M_2 & \ar[l] M_3   & \ar[l]\cdots } 
\end{align}
and the self-map   ${\widehat{\varphi}} \colon \mathfrak{M}_{{\mathcal P}} \to \mathfrak{M}_{{\mathcal P}}$ induced by the collection $\{\varphi_{i_{\ell}} \mid \ell \geq 0\}$ is ${\varepsilon}$-homotopic to $h$. Moreover, for each $\ell \geq 0$, the map $\varphi_{i_{\ell}}$ induces a monomorphism between the fundamental groups of $M_{i_{\ell}}$ and $M_{\ell}$ whose image has finite index.

\label{def-odometer}
Let $\Gamma$ be a finitely generated group and ${\mathfrak{X}}$ be a Cantor space. Let $d_{\mathfrak{X}}$ be a metric on ${\mathfrak{X}}$ compatible with the topology. We say that an action   
$\Phi \colon \Gamma \times {\mathfrak{X}} \to {\mathfrak{X}}$ is an \emph{odometer} if it is minimal and equicontinuous.

\label{def-isomorphism}
Odometer actions $({\mathfrak{X}}_1, \Gamma_1, \Phi_1)$ and $({\mathfrak{X}}_2, \Gamma_2, \Phi_2)$ are said to be \emph{isomorphic}  if there is a homeomorphism $h \colon {\mathfrak{X}}_1 \to {\mathfrak{X}}_2$ and group isomorphism $\Theta \colon \Gamma_1 \to \Gamma_2$ such that 
\begin{equation}\label{eq-isomorphism}
\Phi_1(g) = h^{-1} \circ \Phi_2(\Theta(g)) \circ h   \in   {\rm Homeo}({\mathfrak{X}}_1) \   \textrm{for  all} \ g \in \Gamma_1 \ .
\end{equation}
The map  $h$ is said to be an \emph{isomorphism} when    ${\mathfrak{X}}_1 = {\mathfrak{X}}_2$ and $\Gamma_1 = \Gamma_2$. In this case,   $\Theta \in {\rm Aut}(\Gamma)$ can be viewed as a ``uniform time change'' for the action.

The isomorphism $h$ is an \emph{automorphism}   if ${\mathfrak{X}}_1 = {\mathfrak{X}}_2$, $\Gamma_1 = \Gamma_2$, and $\Theta \colon \Gamma \to \Gamma$ is the identity.

\label{def-normalizer}
Let $({\mathfrak{X}}, \Gamma, \Phi)$ be an odometer action. Define the isomorphism  group  
\begin{equation}\label{eq-normalizer}
{\mathfrak{I}}({\mathfrak{X}}, \Gamma, \Phi) = \{ h \in {\rm Homeo}({\mathfrak{X}})  \mid h ~ {\rm is \ an \ isomorphism \ of \ the \ action}\} \ .
\end{equation}
  The  automorphisms   form a normal subgroup
\begin{equation}\label{eq-auto}
{\mathfrak{I}}_0({\mathfrak{X}}, \Gamma, \Phi) = \{ h  \in {\rm Homeo}({\mathfrak{X}})  \mid h ~ {\rm is \ an \ automorphism \ of \ the \ action}\} \ .
\end{equation}
The  quotient group 
\begin{equation}\label{eq-rep}
{\mathfrak{Q}}({\mathfrak{X}}, \Gamma, \Phi) = {\mathfrak{I}}({\mathfrak{X}}, \Gamma, \Phi)/{\mathfrak{I}}_0({\mathfrak{X}}, \Gamma, \Phi) \  
\end{equation}
then has a representation $\Theta \colon {\mathfrak{Q}}({\mathfrak{X}}, \Gamma, \Phi) \to {\rm Aut}(\Gamma)$.

\label{def-RE}
Odometers  $\Phi \colon \Gamma \times {\mathfrak{X}} \to {\mathfrak{X}}$ and  $\Phi' \colon \Gamma' \times {\mathfrak{X}}' \to {\mathfrak{X}}'$ are \emph{return equivalent} if there exist adapted sets $U \subset {\mathfrak{X}}$ and $U' \subset {\mathfrak{X}}'$ and a homeomorphism $h_U \colon U \to U'$ that induces an isomorphism $\Theta_U \colon {\mathcal H}_U \to {\mathcal H}_V$ between the groups
 \begin{eqnarray*}
{\mathcal H}_U & = & {\rm Image}\{\Phi_U \colon \Gamma_U \to  {\rm Homeo}(U)\} \\
{\mathcal H}'_{U'} & = &  {\rm Image}\{\Phi'_{U'} \colon \Gamma'_{U'} \to  {\rm Homeo}(U')\}.
\end{eqnarray*}

\label{def-dyncomm2}
   Let  $({\mathfrak{X}}, \Gamma, \Phi)$   be an odometer action, and $x \in {\mathfrak{X}}$. 
   \begin{enumerate}
\item  A \emph{dynamical commensurator} at $x$  is a homeomorphism $h_U \colon U \to V$, where $U$ and $V$ are adapted subsets with $x \in U \cap V$, such that $h_U(x) = x$, and $h_U$ induces an isomorphism $\Theta_U \colon {\mathcal H}_U \to {\mathcal H}_V$.
\item   Commensurators $h_U \colon U \to V$ and $h_{U'} \colon U' \to V'$ are equivalent if there exists an adapted set $U''$ with $x \in U'' \subset U \cap U'$ such that $h_U|U'' = h'_{U'}|U''$. We   write $(h_U,U,V) \mathrel{\stackrel{\makebox[0pt]{\mbox{\normalfont\tiny c}}}{\sim}} (h'_{U'},U',V')$.
\item   The \emph{dynamical commensurator group} of $({\mathfrak{X}}, \Gamma, \Phi)$ at $x$ is the set of germs of dynamical commensurators,
$$
{\rm Comm}({\mathfrak{X}}, \Gamma, \Phi, x) = \{  h_U \colon U \to V  \mid x \in U \cap V ,  \ h_U \  {\rm is \ a \ commensurator}  \} \slash  \mathrel{\stackrel{\makebox[0pt]{\mbox{\normalfont\tiny c}}}{\sim}}  $$
The equivalence class of $h_U \colon U \to V$ is denoted by $[h_U,U,V]$.
\end{enumerate}

\label{lem-coherentqa}
A topologically free  odometer  $({\mathfrak{X}}, \Gamma, \Phi)$ is coherent.
Conversely, if $\Gamma$ is torsion-free and the action is  coherent, then the action is topologically free.

\label{ex-weakly-branch}
{\rm
For the second example,  suppose that $\Gamma$ is a weakly branch group (see for example \cite{LavrenyukNekrashevych2002,Nekrashevych2005}).
Let  ${\mathfrak{X}}$ be the boundary of the tree $T$ on which the group acts, then the   action of $\Gamma$ on ${\mathfrak{X}}$ is  an effective odometer. Weakly branch groups are defined as subgroups of ${{\rm Aut}}(T)$, and so their action is effective. A property of weakly branch actions is that for any adapted set $U \subset {\mathfrak{X}}$ there is an element $g_U \in \Gamma$ such that $g_U|({\mathfrak{X}} \backslash U)$ is the identity. It follows that for any adapted $U$ there is an infinite number of elements in $\Gamma$ which are trivial on $U$, and so the action of $\Gamma$ on ${\mathfrak{X}}$ is not coherent. 
}

\label{def-uniqueroot}
 A group $\Gamma$ satisfies the \emph{unique root property} if  for any $n\geq 2$ and $g,h \in \Gamma$, 
$g^n = h^n$ implies $g= h$.

\cite[Lemma~2.4]{BartholdiBogopolski2010}\label{lem-uinquerootext}
 Suppose $\Gamma$ satisfies the unique root property, and $H  \subset \Gamma$ has 
finite index, then the natural map ${\rm Aut}(H) \to  {\rm Comm}(\Gamma)$ is injective.

\label{rmk-borelex}
The Borel Conjecture has been proven for many classes of aspherical manifolds:
\begin{itemize}
\item the torus ${\mathbb T}^n$ for all $n \geq 1$,
\item all  infra-nilmanifolds,
\item   closed Riemannian manifolds $Y$ with negative sectional curvatures,
\item   closed Riemannian manifolds $Y$ of dimension $n \ne 3,4$ with non-positive sectional curvatures,
\item all closed irreducible 3-manifolds.
\end{itemize}

\label{lem-simplyconnected}
 Let $\mathfrak{M}_{\Phi}$ be     the suspension of  $(X_{\mathcal G},\Gamma,\Phi)$. Suppose that $L_{\widehat{x}}$ is simply connected, then 
  $\ker ({\mathcal G}) =  \bigcap_{\ell \geq 0} \Gamma_{\ell} = \{e\}$, and hence the action  $(X_{\mathcal G},\Gamma,\Phi)$ is topologically free.

\label{prop-product}
There is an exact sequence 
\begin{equation}\label{eq-isoext}
\{1\} \to  {\mathfrak{A}}_{{\mathcal G}} \stackrel{\rho_{{\mathcal G}}}{\longrightarrow}   {\mathfrak{I}}(X_{{\mathcal G}}, \Gamma, \Phi)  \stackrel{\Theta_{{\mathcal G}}}{\longrightarrow} {\rm Aut}_{{\mathcal G}}(\Gamma) \to \{1\}
\end{equation}

\label{prop-nonhomogeneous}
 $\mu_{{\mathcal G}}$ descends to a continuous injection 
 \begin{equation}\label{eq-tau221}
\overline{\mu}_{{\mathcal G}} \colon   {\mathfrak{A}}_{{\mathcal G}} \times_{\zeta} {\rm Homeo}(\mathfrak{M}_{\Phi} ; L_{\widehat{x}})    \longrightarrow {\rm Homeo}(\mathfrak{M}_{\Phi})  \ .
\end{equation}

\label{thm-normalize}
Let $\mathfrak{M}_{\Phi}$ be a solenoidal manifold. 
Assume the baseleaf $L_{\widehat{x}} \subset \mathfrak{M}_{\Phi}$ is simply connected. Then there is an inclusion of topological spaces
\begin{equation}\label{eq-tau21}
\overline{\mu}_{{\mathcal G}} \colon   {\mathfrak{A}}_{{\mathcal G}} \times_{\zeta}   {\rm Mod}(\mathfrak{M}_{\Phi} ; \widehat{x})     \to {\rm Mod}(\mathfrak{M}_{\Phi})  \ .
\end{equation}

\label{thm-nonhomogeneous2}
  Let   $\mathfrak{M}_{\Phi}$ be a homogeneous   solenoid  with   simply connected baseleaf $L_{\widehat{x}} \subset \mathfrak{M}_{\Phi}$. 
  Then there is a homeomorphism
  \begin{equation}\label{eq-partialproddyn2}
{\rm Mod}(\mathfrak{M}_{\Phi}) \cong  {\mathfrak{G}}_{{\mathcal G}}  \times_{\zeta}   {\rm Mod}(\mathfrak{M}_{\Phi} ; L_{\widehat{x}})     \ .
\end{equation}

\label{cor-BC}
 Let $\mathfrak{M}_{\Phi}$ be a solenoidal manifold. 
Assume the baseleaf $L_{\widehat{x}} \subset \mathfrak{M}_{\Phi}$ is simply connected. Then ${\rm Mod}(\mathfrak{M}_{\Phi})$ contains the subgroup generated by all images of ${\mathfrak{N}}({\mathfrak{D}}_{\gamma})  \  \times_{\zeta}  \  {\rm Mod}(\mathfrak{M}_{\Phi} ; \widehat{y}) $ under the corresponding multiplication map $ \mu_{{\mathcal G}, \widehat{y}}$ for $\widehat{y} =\gamma \cdot \widehat{x} \in X_{{\mathcal G}}$.

\label{thm-nilmcg}
Let $M$ be a nilmanifold with $\Gamma = \pi_1(M,x)$. Then
${\rm Mod}(\widehat{M}) \cong \widehat{\Gamma} \times_{\zeta} {\rm Comm}(\Gamma)$.

\label{thm-pnilmcg}
Let $M$ be a nilmanifold with $\Gamma = \pi_1(M,x)$, $\sigma \colon \Gamma \to  {\rm SL}({\mathbb Z}^n)$ an embedding, and $p > 1$ a prime. Then
${\rm Mod}(\widehat{M}_{\sigma,p}) \cong \widehat{\Gamma}_{{\mathcal G}_{\sigma,p}} \times_{\zeta} {\rm Comm}(X_{{\mathcal G}_{\sigma,p}}, \Gamma, \Phi, x)$.

\label{thm-negcomm}
Let $M$ be a closed connected manifold with constant negative curvature, and let $\Gamma = \pi_1(M,x)$. Then
${\rm Mod}(\widehat{M}) \cong \widehat{\Gamma} \times_{\zeta} {\rm Comm}(\Gamma)$.
